@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=Playfair+Display:wght@400;600;700&display=swap');

/* Override theme page containers to allow full-width blocks */
.entry-content, .post-content, .wp-site-blocks, .site-content, .ast-container, .hello-elementor-content, .site-main {
  max-width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  width: 100% !important;
}

/* Hide Theme Chrome */
.entry-title, .entry-header, .post-title, .page-title, .wp-block-post-title, .site-header, #masthead, .site-branding, .header-footer-group, .theme-header, .custom-header, .nav-container {
  display: none !important;
}

/* Base Scoped Styles */
.ds-homepage {
  --ds-primary: #0066cc;
  --ds-primary-dark: #004c99;
  --ds-accent: #00a651;
  --ds-neutral: #f5f5f5;
  --ds-text-main: #1e293b;
  --ds-text-light: #64748b;
  --ds-bg-white: #ffffff;
  --ds-font-heading: 'Playfair Display', serif;
  --ds-font-body: 'Inter', sans-serif;

  width: 100vw !important;
  max-width: 100vw !important;
  position: relative !important;
  left: 50% !important;
  right: 50% !important;
  margin-left: -50vw !important;
  margin-right: -50vw !important;
  box-sizing: border-box !important;
  overflow-x: hidden !important;
  font-family: var(--ds-font-body);
  color: var(--ds-text-main);
  background: var(--ds-bg-white);
  line-height: 1.6;
}

.ds-homepage * {
  box-sizing: border-box;
}

.ds-homepage img {
  max-width: 100%;
  height: auto;
  display: block;
}

.ds-homepage a {
  text-decoration: none;
  color: inherit;
}

/* Typography */
.ds-homepage h1, .ds-homepage h2, .ds-homepage h3, .ds-homepage h4 {
  font-family: var(--ds-font-heading);
  margin: 0 0 1rem 0;
  line-height: 1.2;
  color: var(--ds-text-main);
}

.ds-gradient-text {
  background: linear-gradient(135deg, var(--ds-primary) 0%, var(--ds-primary-dark) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.ds-gradient-text-light {
  background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Layout & Containers */
.ds-container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.ds-section {
  padding: clamp(4rem, 10vw, 8rem) 0;
  position: relative;
  z-index: 1;
}

.ds-bg-neutral {
  background-color: var(--ds-neutral);
}

/* Badges */
.ds-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 1.25rem;
  background: rgba(0, 102, 204, 0.08);
  color: var(--ds-primary);
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 1px solid rgba(0, 102, 204, 0.15);
  margin-bottom: 1.25rem;
}

.ds-badge-light {
  background: rgba(255,255,255,0.12);
  color: #ffffff;
  border-color: rgba(255,255,255,0.2);
}

/* Buttons */
.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  border-radius: 50px;
  font-weight: 600;
  font-size: 1rem;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  border: none;
}

.ds-btn-small {
  padding: 0.6rem 1.5rem;
  font-size: 0.875rem;
}

.ds-btn-primary {
  background: linear-gradient(135deg, var(--ds-primary) 0%, var(--ds-primary-dark) 100%);
  color: #ffffff;
  box-shadow: 0 4px 15px rgba(0, 102, 204, 0.3);
}

.ds-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(0, 102, 204, 0.4);
  color: #ffffff;
}

.ds-btn-secondary {
  background: #ffffff;
  color: var(--ds-primary);
  border: 1px solid rgba(0, 102, 204, 0.2);
}

.ds-btn-secondary:hover {
  border-color: var(--ds-primary);
  background: rgba(0, 102, 204, 0.05);
  transform: translateY(-2px);
}

/* Header & Navigation */
.ds-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 4px 30px rgba(0,0,0,0.03);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  padding: 1.25rem 0;
}

.ds-header.ds-scrolled {
  background: rgba(255, 255, 255, 0.95);
  padding: 0.75rem 0;
  box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.ds-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ds-logo-text {
  font-family: var(--ds-font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--ds-primary);
}

.ds-nav {
  display: none;
}

.ds-nav-link {
  position: relative;
  padding: 0.5rem 0;
  font-weight: 500;
  color: rgba(15, 23, 42, 0.8);
  transition: color 0.3s ease;
}

.ds-nav-link::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--ds-primary);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.ds-nav-link:hover {
  color: var(--ds-primary);
}

.ds-nav-link:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.ds-mobile-menu-toggle {
  display: none;
}

.ds-mobile-menu-label {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 30px;
  height: 21px;
  cursor: pointer;
  z-index: 1001;
}

.ds-hamburger-line {
  display: block;
  height: 3px;
  width: 100%;
  background: var(--ds-text-main);
  border-radius: 3px;
  transition: all 0.3s ease;
}

.ds-header-cta {
  display: none;
}

.ds-mobile-only {
  display: inline-flex;
  margin-top: 1rem;
}

/* Mobile Menu Hack */
#ds-mobile-menu-toggle:checked ~ .ds-nav {
  display: flex;
  flex-direction: column;
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  background: #ffffff;
  padding: 1.5rem;
  box-shadow: 0 10px 15px rgba(0,0,0,0.05);
  gap: 1rem;
  border-top: 1px solid rgba(0,0,0,0.05);
}

#ds-mobile-menu-toggle:checked ~ .ds-mobile-menu-label .ds-hamburger-line:nth-child(1) {
  transform: translateY(9px) rotate(45deg);
}
#ds-mobile-menu-toggle:checked ~ .ds-mobile-menu-label .ds-hamburger-line:nth-child(2) {
  opacity: 0;
}
#ds-mobile-menu-toggle:checked ~ .ds-mobile-menu-label .ds-hamburger-line:nth-child(3) {
  transform: translateY(-9px) rotate(-45deg);
}

/* Hero Section */
.ds-hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  padding: 6rem 0;
  clip-path: ellipse(180% 100% at 50% 0%);
  overflow: hidden;
}

.ds-hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
}

.ds-hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ds-hero-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, rgba(0, 20, 40, 0.9) 0%, rgba(0, 40, 80, 0.7) 50%, rgba(0, 102, 204, 0.4) 100%);
}

.ds-hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.ds-hero-title {
  font-size: clamp(3rem, 6vw, 5rem);
  color: #ffffff;
  margin-bottom: 1.5rem;
}

.ds-hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.25rem);
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 2.5rem;
  max-width: 600px;
}

.ds-hero-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Intro & Stats */
.ds-intro-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
  align-items: center;
}

.ds-section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1.5rem;
}

.ds-section-desc {
  font-size: 1.125rem;
  color: var(--ds-text-light);
  max-width: 700px;
  margin-bottom: 2rem;
}

.ds-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 2rem;
}

.ds-stat-card {
  text-align: center;
  padding: 2rem;
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.03);
  border: 1px solid rgba(0,0,0,0.05);
}

.ds-stat-number {
  font-family: var(--ds-font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--ds-primary);
  margin-bottom: 0.5rem;
}

.ds-stat-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--ds-text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Cards & Services */
.ds-card {
  background: #ffffff;
  border-radius: 20px;
  border: 1px solid rgba(0,0,0,0.05);
  box-shadow: 0 10px 30px rgba(0,0,0,0.02);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  overflow: hidden;
}

.ds-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(800px circle at var(--mouse-x, 0) var(--mouse-y, 0), rgba(0, 102, 204, 0.06), transparent 40%);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
  z-index: 1;
}

.ds-card:hover::before {
  opacity: 1;
}

.ds-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 40px rgba(0,0,0,0.08);
  border-color: rgba(0, 102, 204, 0.3);
}

.ds-services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 3rem;
}

.ds-service-img-wrap {
  width: 100%;
  height: 240px;
  overflow: hidden;
}

.ds-service-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-card:hover .ds-service-img {
  transform: scale(1.06);
}

.ds-service-content {
  padding: 2rem;
  position: relative;
  z-index: 2;
}

.ds-service-title {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.ds-service-desc {
  color: var(--ds-text-light);
  font-size: 1rem;
}

/* Reviews */
.ds-reviews-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 3rem;
}

.ds-review-card {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.ds-stars {
  color: #fbbf24;
  font-size: 1.25rem;
  margin-bottom: 1rem;
  letter-spacing: 2px;
}

.ds-review-text {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 2rem;
  color: var(--ds-text-main);
}

.ds-review-author {
  display: flex;
  flex-direction: column;
}

.ds-review-author strong {
  font-family: var(--ds-font-heading);
  font-size: 1.125rem;
  color: var(--ds-primary);
}

.ds-review-author span {
  font-size: 0.875rem;
  color: var(--ds-text-light);
}

/* Gallery */
.ds-gallery-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.ds-gallery-item {
  border-radius: 20px;
  overflow: hidden;
  height: 250px;
}

.ds-gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-gallery-item:hover img {
  transform: scale(1.06);
}

/* Contact */
.ds-contact-wrapper {
  display: grid;
  grid-template-columns: 1fr;
  overflow: hidden;
}

.ds-contact-info {
  padding: 3rem;
}

.ds-contact-details {
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.ds-contact-item strong {
  display: block;
  color: var(--ds-primary);
  margin-bottom: 0.25rem;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.ds-contact-item a, .ds-contact-item p {
  color: var(--ds-text-main);
  font-size: 1.125rem;
}

.ds-contact-item a:hover {
  color: var(--ds-accent);
}

.ds-mt-4 {
  margin-top: 2rem;
}

.ds-contact-map {
  height: 400px;
  position: relative;
}

.ds-map-placeholder {
  width: 100%;
  height: 100%;
  position: relative;
}

.ds-map-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ds-map-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0,0,0,0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s;
}

.ds-contact-map:hover .ds-map-overlay {
  opacity: 1;
}

/* Footer */
.ds-footer {
  background: #0f172a;
  color: #ffffff;
  padding: 4rem 0 2rem;
}

.ds-footer-inner {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  margin-bottom: 3rem;
  text-align: center;
}

.ds-footer-brand h3 {
  color: #ffffff;
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.ds-footer-brand p {
  color: #94a3b8;
}

.ds-footer-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.ds-footer-links a {
  color: #cbd5e1;
  transition: color 0.3s;
}

.ds-footer-links a:hover {
  color: var(--ds-accent);
}

.ds-footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  color: #64748b;
  font-size: 0.875rem;
}

/* Animations & Effects */
.ds-reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-reveal.visible, .ds-reveal.ds-visible {
  opacity: 1;
  transform: translateY(0);
}

.ds-delay-1 { transition-delay: 0.15s; }
.ds-delay-2 { transition-delay: 0.3s; }
.ds-delay-3 { transition-delay: 0.45s; }
.ds-delay-4 { transition-delay: 0.6s; }

.ds-glow-1, .ds-glow-2 {
  position: absolute;
  width: clamp(200px, 40vw, 400px);
  height: clamp(200px, 40vw, 400px);
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.06;
  pointer-events: none;
  z-index: 0;
}

.ds-glow-1 {
  background: var(--ds-primary);
  top: 15%;
  left: -10%;
  animation: dsFloat 18s infinite alternate ease-in-out;
}

.ds-glow-2 {
  background: var(--ds-accent);
  bottom: 25%;
  right: -10%;
  animation: dsFloat 24s infinite alternate-reverse ease-in-out;
}

@keyframes dsFloat {
  0% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(6%, 6%) scale(1.08); }
  100% { transform: translate(0, 0) scale(1); }
}

/* Cursor */
.ds-cursor {
  display: none;
}
.ds-cursor-dot {
  display: none;
}

@media (pointer: fine) {
  .ds-cursor {
    display: block;
    width: 40px;
    height: 40px;
    border: 2px solid var(--ds-primary);
    border-radius: 50%;
    position: fixed;
    transform: translate(-50%, -50%);
    pointer-events: none;
    transition: width 0.3s, height 0.3s, transform 0.1s ease-out, border-color 0.3s;
    z-index: 9999;
  }
  .ds-cursor-dot {
    display: block;
    width: 8px;
    height: 8px;
    background: var(--ds-primary);
    border-radius: 50%;
    position: fixed;
    transform: translate(-50%, -50%);
    pointer-events: none;
    transition: transform 0.05s ease-out;
    z-index: 9999;
  }
}

/* Responsive Breakpoints */
@media (min-width: 768px) {
  .ds-mobile-menu-label {
    display: none;
  }
  .ds-nav {
    display: flex;
    gap: 2rem;
    align-items: center;
  }
  .ds-header-cta {
    display: block;
  }
  .ds-mobile-only {
    display: none;
  }
  .ds-intro-grid {
    grid-template-columns: 1fr 1fr;
  }
  .ds-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .ds-reviews-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .ds-gallery-grid {
    grid-template-columns: repeat(4, 1fr);
  }
  .ds-contact-wrapper {
    grid-template-columns: 1fr 1fr;
  }
  .ds-contact-map {
    height: auto;
  }
  .ds-footer-inner {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
  .ds-footer-links {
    flex-direction: row;
    gap: 2rem;
  }
}

@media (min-width: 1024px) {
  .ds-services-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-homepage * {
    transition: none !important;
    transform: none !important;
    animation: none !important;
  }
}
